const wh = $('1. Webhook').first();
const headers = wh.json.headers || {};
const filename = headers['x-original-filename'] || 'audio.mp3';
const ext = (filename.split('.').pop() || 'mp3').toLowerCase();
// UUID v4 manual (sandbox bloqueia crypto)
const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});
const meeting_id = uuid;
const now = new Date();
const year  = String(now.getUTCFullYear());
const month = String(now.getUTCMonth() + 1).padStart(2, '0');
const recorded_at = headers['x-recorded-at'] || now.toISOString();

return [{
  json: {
    meeting_id,
    year, month,
    source: headers['x-source'] || 'macbook',
    meeting_type: headers['x-meeting-type'] || 'desconhecido',
    original_filename: filename,
    recorded_at,
    audio_size_bytes: parseInt(headers['x-audio-size'] || '0', 10),
    ext,
    audio_path: `/audios/${meeting_id}.${ext}`
  },
  binary: wh.binary
}];

// Mantém JSON do step anterior (save-audio response) e restaura binary do step 3
// (HTTP Request consome o binary, mas Whisper precisa dele)
return [{
  json: $json,
  binary: $('3. Prepare Metadata').first().binary
}];

// Parseia o JSON retornado pelo GPT e prepara items para INSERT em tarefas.
const meetingId = $('3. Prepare Metadata').item.json.meeting_id;
const raw = $input.first().json;

// O nó openAi v1.7 retorna o JSON em diferentes shapes — normaliza.
let parsed;
if (raw.message && raw.message.content) {
  parsed = typeof raw.message.content === 'string' ? JSON.parse(raw.message.content) : raw.message.content;
} else if (raw.content) {
  parsed = typeof raw.content === 'string' ? JSON.parse(raw.content) : raw.content;
} else if (raw.text) {
  parsed = typeof raw.text === 'string' ? JSON.parse(raw.text) : raw.text;
} else if (raw.summary && Array.isArray(raw.actions)) {
  parsed = raw;
} else {
  throw new Error('Não foi possível parsear resposta do GPT: ' + JSON.stringify(raw).slice(0, 500));
}

const { summary = '', actions = [] } = parsed;
const rawJson = JSON.stringify(parsed);

if (!actions.length) {
  return [{
    json: {
      meeting_id: meetingId,
      summary,
      raw_ai_response: rawJson,
      no_actions: true
    }
  }];
}

return actions.map((a, i) => ({
  json: {
    meeting_id: meetingId,
    summary,
    raw_ai_response: rawJson,
    titulo: a.titulo || '(sem título)',
    descricao: a.descricao || '',
    owner: a.owner || 'vitor',
    prazo: a.prazo_iso || null,
    prazo_text: a.prazo_text || null,
    prioridade: ['baixa','media','alta','urgente'].includes(a.prioridade) ? a.prioridade : 'media',
    evidencia: a.evidencia || '',
    idx: i,
    total: actions.length
  }
}));

// Monta a mensagem do WhatsApp
const meetingId = $('3. Prepare Metadata').item.json.meeting_id;
const summary = $('9. Parse Actions').first().json.summary;
const items = $('9. Parse Actions').all().map(i => i.json).filter(j => !j.no_actions);

const minhas = items.filter(i => i.owner === 'vitor');
const delegadas = items.filter(i => i.owner !== 'vitor');
const formatPrazo = (p) => {
  if (!p) return '';
  try {
    const d = new Date(p);
    return ' _(até ' + d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) + ')_';
  } catch { return ''; }
};
const emojiPrio = { urgente: '🔴', alta: '🟠', media: '🟡', baixa: '⚪' };

let msg = '🎙️ *Reunião processada*\n\n';
msg += '_' + summary + '_\n\n';

if (minhas.length) {
  msg += '✅ *Minhas ações* (' + minhas.length + ')\n';
  minhas.forEach(t => {
    msg += (emojiPrio[t.prioridade] || '🟡') + ' ' + t.titulo + formatPrazo(t.prazo) + '\n';
  });
  msg += '\n';
}

if (delegadas.length) {
  msg += '👥 *Combinei com outros* (' + delegadas.length + ')\n';
  delegadas.forEach(t => {
    msg += (emojiPrio[t.prioridade] || '🟡') + ' *' + t.owner + ':* ' + t.titulo + formatPrazo(t.prazo) + '\n';
  });
  msg += '\n';
}

if (!minhas.length && !delegadas.length) {
  msg += '_(nenhuma ação concreta extraída desta reunião)_\n';
}

const frontendUrl = 'https://acoes.vitorgambetti.com.br';
msg += '🔗 ' + frontendUrl + '/reunioes/' + meetingId;

return [{ json: { text: msg, meeting_id: meetingId, n_tarefas: items.length } }];
